mutation_source.object_graph_alloc_style:
mutateObjectsAlloc(s, pass) {
    const nodes = s.nodes;
    for (let i = 0; i < nodes.length; i++) {
      const o = nodes[i];
      o.payload = { x: o.payload.x + 0.5, y: o.payload.y + 0.25, z: o.payload.z - 0.125 };
      o.timestamp += 1;
    }
    flipObjectEdges(s.edges, pass);
  }

mutation_source.object_graph_inplace_style:
mutateObjectsInplace(s, pass) {
    const nodes = s.nodes;
    for (let i = 0; i < nodes.length; i++) {
      const o = nodes[i], p = o.payload;
      p.x += 0.5; p.y += 0.25; p.z -= 0.125;
      o.timestamp += 1;
    }
    flipObjectEdges(s.edges, pass);
  }

mutation_source.slab:
mutateSlab(s, pass) {
    const view = s.view;
    for (let i = 0; i < s.n; i++) {
      const o = i * RECORD_BYTES;
      view.setFloat64(o + 16, view.getFloat64(o + 16, true) + 0.5, true);
      view.setFloat64(o + 24, view.getFloat64(o + 24, true) + 0.25, true);
      view.setFloat64(o + 32, view.getFloat64(o + 32, true) - 0.125, true);
      view.setFloat64(o + 8, view.getFloat64(o + 8, true) + 1, true);
    }
    flipSlabEdges(s, pass);
  }

mutation_source.object_graph_alloc_style:
mutateObjectsAlloc(s, pass) {
    const nodes = s.nodes;
    for (let i = 0; i < nodes.length; i++) {
      const o = nodes[i];
      o.turns.push({ sender: 'user', content: 'exec', ts: o.turns[1].ts + 1 });
      o.turns.shift();
      o.metrics = { latencyMs: o.metrics.latencyMs * 0.5 + 1, tokens: o.metrics.tokens + 1 };
    }
    flipObjectEdges(s.edges, pass);
  }

mutation_source.object_graph_inplace_style:
mutateObjectsInplace(s, pass) {
    const nodes = s.nodes;
    for (let i = 0; i < nodes.length; i++) {
      const o = nodes[i], t0 = o.turns[0], t1 = o.turns[1];
      t0.sender = t1.sender; t0.content = t1.content; t0.ts = t1.ts;
      t1.sender = 'user'; t1.content = 'exec'; t1.ts = t0.ts + 1;
      o.metrics.latencyMs = o.metrics.latencyMs * 0.5 + 1;
      o.metrics.tokens += 1;
    }
    flipObjectEdges(s.edges, pass);
  }

mutation_source.slab:
mutateSlab(s, pass) {
    const view = s.view;
    for (let i = 0; i < s.n; i++) {
      const o = i * RECORD_BYTES;
      const ts1 = view.getFloat64(o + 40, true);
      view.setFloat64(o + 24, ts1, true);
      view.setUint8(o + 32, view.getUint8(o + 48));
      view.setUint8(o + 33, view.getUint8(o + 49));
      view.setFloat64(o + 40, ts1 + 1, true);
      view.setUint8(o + 48, 1);
      view.setUint8(o + 49, 1);
      view.setFloat64(o + 56, view.getFloat64(o + 56, true) * 0.5 + 1, true);
      view.setUint32(o + 64, view.getUint32(o + 64, true) + 1, true);
    }
    flipSlabEdges(s, pass);
  }

mutation_source.object_graph_alloc_style:
mutateObjectsAlloc(s, pass) {
    const nodes = s.nodes;
    for (let i = 0; i < nodes.length; i++) {
      const f = nodes[i];
      f.chunk = Buffer.alloc(CHUNK_BYTES, (pass + i) & 255);
      f.pts += 8.333;
    }
    flipObjectEdges(s.edges, pass);
  }

mutation_source.object_graph_inplace_style:
mutateObjectsInplace(s, pass) {
    const nodes = s.nodes;
    for (let i = 0; i < nodes.length; i++) {
      const f = nodes[i];
      f.chunk.fill((pass + i) & 255);
      f.pts += 8.333;
    }
    flipObjectEdges(s.edges, pass);
  }

mutation_source.slab:
mutateSlab(s, pass) {
    const view = s.view, planeView = s.planeView;
    for (let i = 0; i < s.n; i++) {
      const o = i * RECORD_BYTES;
      planeView.fill((pass + i) & 255, i * CHUNK_BYTES, (i + 1) * CHUNK_BYTES);
      view.setFloat64(o + 8, view.getFloat64(o + 8, true) + 8.333, true);
    }
    flipSlabEdges(s, pass);
  }

mutation_source.object_graph_alloc_style:
mutateObjectsAlloc(s, pass) {
    const nodes = s.nodes, dt = 1 / 120;
    for (let i = 0; i < nodes.length; i++) {
      const p = nodes[i];
      const np = [p.pos[0] + p.vel[0] * dt, p.pos[1] + p.vel[1] * dt, p.pos[2] + p.vel[2] * dt];
      p.prevPos = p.pos;
      p.pos = np;
    }
    flipObjectEdges(s.edges, pass);
  }

mutation_source.object_graph_inplace_style:
mutateObjectsInplace(s, pass) {
    const nodes = s.nodes, dt = 1 / 120;
    for (let i = 0; i < nodes.length; i++) {
      const p = nodes[i], pos = p.pos, prev = p.prevPos, vel = p.vel;
      prev[0] = pos[0]; prev[1] = pos[1]; prev[2] = pos[2];
      pos[0] += vel[0] * dt; pos[1] += vel[1] * dt; pos[2] += vel[2] * dt;
    }
    flipObjectEdges(s.edges, pass);
  }

mutation_source.slab:
mutateSlab(s, pass) {
    const P = s.view, dt = 1 / 120;
    for (let i = 0; i < s.n; i++) {
      const o = i * STRIDE;
      P[o + 4] = P[o]; P[o + 5] = P[o + 1]; P[o + 6] = P[o + 2];
      P[o] += P[o + 8] * dt; P[o + 1] += P[o + 9] * dt; P[o + 2] += P[o + 10] * dt;
    }
    flipSlabEdges(s, pass);
  }
